INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Effizienz in IT nur auf Geschwindigkeit beschränkt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Ressourcennutzung"}, {"text": "Ja", "correct": false, "because": "Breiterer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt Effizienz in IT-Systemen?', 3, '[{"text": "Ressourcen optimal nutzen", "correct": true, "because": "Leistung und Kosten"}, {"text": "Nur Hardware verbessern", "correct": false, "because": "Auch Software"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Sicherheitsfokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Effizienz in IT?', 5, '[{"text": "Softwareoptimierung", "correct": true, "because": "Code-Leistung"}, {"text": "Hardware-Ressourcen", "correct": true, "because": "CPU, RAM"}, {"text": "Papierqualität", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Effizienz reduziert Ressourcenverbrauch. b) Sie betrifft nur Server.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Alle Systeme"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Steigerung der Effizienz?', 4, '[{"text": "Prozessorleistung", "correct": false, "because": "Wichtiger Faktor"}, {"text": "Code-Optimierung", "correct": false, "because": "Leistung steigern"}, {"text": "Monitorgröße", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Effizienz nur Hardware betrifft?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Software"}, {"text": "Ja", "correct": false, "because": "Breiterer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode steigert die Effizienz von Software?', 3, '[{"text": "Code-Optimierung", "correct": true, "because": "Laufzeit verbessern"}, {"text": "Hardware-Upgrade", "correct": false, "because": "Sekundär"}, {"text": "Papierdokumentation", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen fördern Effizienz in IT?', 5, '[{"text": "Automatisierung", "correct": true, "because": "Manuelle Aufgaben reduzieren"}, {"text": "Lastverteilung", "correct": true, "because": "Ressourcen ausbalancieren"}, {"text": "Manuelle Eingabe", "correct": false, "because": "Ineffizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Effizienz spart Energie. b) Sie verlangsamt Systeme. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Leistung steigern"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für mehr Effizienz?', 4, '[{"text": "Optimierte Algorithmen", "correct": false, "because": "Leistung steigern"}, {"text": "Ressourcenmanagement", "correct": false, "because": "Nutzung verbessern"}, {"text": "Papierhandbücher", "correct": true, "because": "Digital ausreichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Effizienz nur für große Systeme wichtig?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Systeme"}, {"text": "Ja", "correct": false, "because": "Allgemein relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologien fördern Effizienz?', 4, '[{"text": "Cloud-Computing", "correct": true, "because": "Ressourcen skalieren"}, {"text": "Virtualisierung", "correct": true, "because": "Hardware nutzen"}, {"text": "Manuelle Prozesse", "correct": false, "because": "Ineffizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Effizienz keine Kosten spart. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Ressourcen sparen"}, {"text": "Ja", "correct": false, "because": "Kostensenkung möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich für Effizienz?', 3, '[{"text": "Ressourcennutzung", "correct": true, "because": "Optimaler Einsatz"}, {"text": "Papierdokumente", "correct": false, "because": "Irrelevant"}, {"text": "Langsame Prozesse", "correct": false, "because": "Schnelligkeit zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Effizienz verbessert die Leistung. b) Sie erhöht den Ressourcenverbrauch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verbrauch sinkt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ansätze steigern die Effizienz?', 5, '[{"text": "Load-Balancing", "correct": true, "because": "Last verteilen"}, {"text": "Caching", "correct": true, "because": "Zugriff beschleunigen"}, {"text": "Manuelle Steuerung", "correct": false, "because": "Ineffizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Effizienz unwichtig?', 3, '[{"text": "Laufzeit", "correct": false, "because": "Leistungsfaktor"}, {"text": "Ressourcen", "correct": false, "because": "Nutzung zentral"}, {"text": "Schriftart", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann Effizienz die Kosten senken?', 3, '[{"text": "Ja", "correct": true, "because": "Weniger Ressourcen"}, {"text": "Nein", "correct": false, "because": "Kostensenkung möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Effizienz nur Software betrifft?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Hardware"}, {"text": "Ja", "correct": false, "because": "Systemweit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist für Effizienz zentral?', 4, '[{"text": "Optimale Ressourcennutzung", "correct": true, "because": "Kernprinzip"}, {"text": "Langsame Prozesse", "correct": false, "because": "Ineffizient"}, {"text": "Papierdokumente", "correct": false, "because": "Irrelevant"}]');
